import { test, expect } from '@playwright/test';

test.describe('API Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/'); // Replace with the actual URL of the application
  });

  test('should display error banner on API call failure', async ({ page }) => {
    await page.route('**/api/endpoint', (route) => {
      route.fulfill({
        status: 500,
        body: JSON.stringify({ error: 'Internal Server Error' }),
      });
    });

    await page.click(getByRole('button', { name: /submit/i })); // Replace with the actual button that triggers the API call

    const errorBanner = await page.getByRole('alert');
    await expect(errorBanner).toBeVisible();
    await expect(errorBanner).toHaveText(/internal server error/i);
  });

  test('should not display error banner on successful API call', async ({ page }) => {
    await page.route('**/api/endpoint', (route) => {
      route.fulfill({
        status: 200,
        body: JSON.stringify({ success: true }),
      });
    });

    await page.click(getByRole('button', { name: /submit/i })); // Replace with the actual button that triggers the API call

    const errorBanner = await page.getByRole('alert');
    await expect(errorBanner).not.toBeVisible();
  });
});
